L000361	\subsection{Overdamped Langevin dynamics} \label{sec-fffri-over}
L000362	We consider the overdamped Ito-Langevin equations for $\bm{x} \in \mathbb{R}^D$,
L000363	\begin{align}
L000364	\dot{\bm{x}}(t) = \bm{a}(\bm{x}(t)) + \epsilon \sum_{q = 1}^{Q} \bm{y}_q(\bm{x}(t)) \phi_q(t) + \sqrt{2 \bm{B}(\bm{x}(t))} \cdot \bm{\xi}(t) \label{langevin} .
L000365	\end{align}
L000366	Here $\bm{a}(\bm{x})$ is the drift vector and $\bm{B}(\bm{x})$ is the positive definite diffusion matrix; $\sqrt{\bm{B}(\bm{x})}$ denotes its unique positive definite matrix square root.
L000367	$\odot$ denotes the combination of matrix- and Ito-product, and $\bm{\xi}(t)$ is a vector of mutually uncorrelated, Gaussian white noises, $\Av{\xi_h(t) \xi_j(t')} = \delta_{h j} \delta(t-t')$.
L000368	The vectors $\bm{y}_q(\bm{x})$ represent small perturbations ($\epsilon \ll 1$) to the drift vector, whose time-dependence is encoded by the functions $\phi_q(t)$.
L000369	\eqref{langevin-over} of the main text is recovered for $\bm{a}(\bm{x}) = \frac{1}{\gamma} \bm{f}(\bm{x})$, $\bm{y}_q(\bm{x}) = \frac{1}{\gamma} \bm{g}_q(\bm{x})$ and $\bm{B}(\bm{x}) = T/\gamma \bm{I}$ with $\bm{I}$ the identity matrix.
L000370	We assume that, without the perturbation, the system is in a steady state characterized by the probability density $p_\text{st}(\bm{x})$, which obeys the steady-state Fokker-Planck equation \cite{Risken1986}
L000371	\begin{align}
L000372	0 &= - \grad_x \big( \bm{\nu}_\text{st}(\bm{x}) p_\text{st}(\bm{x}) \big) \quad \text{with} \label{fpe-steady} \\
L000373	\bm{\nu}_\text{st}(\bm{x}) &= \bm{a}(\bm{x}) - \grad \bm{B}(\bm{x}) - \bm{B}(\bm{x}) \grad \ln p_\text{st}(\bm{x}) \n ,
L000374	\end{align}
L000375	where $\bm{\nu}_\text{st}(\bm{x})$ is called the steady-state local mean velocity \cite{Seifert2010a}, which quantifies the magnitude of flows in the (generally) non-equilibrium steady state.
L000376	Here, we defined the vector-valued divergence of a matrix by $(\grad \bm{B}(\bm{x}))_{j} = \sum_{h} \partial_{x_h} B_{h j}(\bm{x})$.
L000377	In order to avoid confusion with the Ito-product, we omit the scalar product in denoting the divergence; any product between two vector-valued quantities is implicitly assumed to be a scalar product unless noted otherwise.
L000378	Note that the steady state is in equilibrium (satisfied detailed balance) if and only if the local mean velocity vanishes identically; the steady-state entropy production rate is
L000379	\begin{align}
L000380	\sigma_\text{st} = \Av{\bm{\nu}_\text{st} \bm{B}^{-1} \bm{\nu}_\text{st}}_\text{st},
L000381	\end{align}
L000382	which is strictly positive for any non-zero $\bm{\nu}_\text{st}(\bm{x})$ as $\bm{B}(\bm{x})$ is assumed to be positive definite.
L000383	
L000384	\subsubsection{Observables and power-spectral density}
L000385	We focus on $K$ scalar observables that each consist of a configuration-dependent contribution $z_k(\bm{x}(t))$ and a current-like contribution $\bm{w}_k(\bm{x}(t)) \circ \dot{\bm{x}}(t)$, where $\circ$ is the Stratonovich-product,
L000386	\begin{align}
L000387	r_k(t) = z_k(\bm{x}(t)) + \bm{w}_k(\bm{x}(t)) \circ \dot{\bm{x}}(t) \label{observable} .
L000388	\end{align}
L000389	The steady-state average of $r_k(t)$ is given by
L000390	\begin{align}
L000391	\Av{r_k}_\text{st} = \int d\bm{x} \ \Big( z_k(\bm{x}) + \bm{w}_k(\bm{x}) \bm{\nu}_\text{st}(\bm{x}) \Big) p_\text{st}(\bm{x}) =  \Av{z_k}_\text{st} + \Av{\bm{w}_k \bm{\nu}_\text{st}}_\text{st} .
L000392	\end{align}
L000393	We characterize the fluctuations of the observables in the steady state using their covariances,
L000394	\begin{align}
L000395	C_{kl}(t) = \text{Cov}_\text{st}(r_k(t),r_l(0)) = \Av{r_k(t) r_l(0)}_\text{st} - \Av{r_k}_\text{st} \Av{r_l}_\text{st} ,
L000396	\end{align}
L000397	where the subscript st indicates that the average is taken with respect to the unperturbed steady state for $\epsilon = 0$.
L000398	Due to time-translation invariance, the covariance matrix $\bm{C}(t)$ only depends on the time-lag $t$.
L000399	However, since the system described by \eqref{langevin} is generally out of equilibrium even in the steady state, $\bm{C}(t)$ is not a symmetric matrix; rather we have $\bm{C}^\text{T}(t) = \bm{C}(-t)$.
L000400	Equivalently, we can characterize the correlations by the power-spectral density matrix, which is the Fourier-transform of the covariance matrix $\bm{C}(t)$,
L000401	\begin{align}
L000402	\bmc{S}(\omega) = \int_{-\infty}^\infty dt \ e^{i \omega t} \bm{C}(t) \label{power-spectral-density} .
L000403	\end{align}
L000404	The power-spectral density $\bmc{S}(\omega)$ is a Hermitian, positive definite matrix.
L000405	It is real and symmetric when $\bm{C}(t)$ is symmetric, that is, when the system \eqref{langevin} is in equilibrium and thus time-reversal symmetric.
L000406	Note that the power spectrum can equivalently be defined by introducing the finite-time Fourier transform of the observables,
L000407	\begin{align}
L000408	\hat{r}_k(\omega,\tau) = \int_0^\tau dt \ e^{i \omega t} r_k(t).
L000409	\end{align}
L000410	By the Wiener-Khinchine theorem, we then obtain
L000411	\begin{align}
L000412	\mathcal{S}_{kl}(\omega) = \lim_{\tau \rightarrow \infty} \frac{1}{\tau} \text{Cov}_\text{st}\big(\hat{r}_k(\omega,\tau),\hat{r}_l^*(\omega,\tau) \big),
L000413	\end{align}
L000414	where $*$ denotes complex conjugation.
L000415	This identity shows that $\bmc{S}(\omega)$ is itself a covariance matrix of complex observables, which implies its positive-definiteness.
L000416	
L000417	\subsubsection{Response and fluctuation-dissipation theorem}
L000418	Next, we want to characterize the response of the observables to the perturbations.
L000419	The change in the average value of an observable is
L000420	\begin{align}
L000421	\Delta \Av{r_k(t)} = \Av{r_k(t)}_\epsilon - \Av{r_k}_\text{st} ,
L000422	\end{align}
L000423	where $\Av{r_k}_\epsilon$ denotes the average of the observable for $\epsilon > 0$.
L000424	We focus on the linear response regime $\epsilon \rightarrow 0$, where we have
L000425	\begin{align}
L000426	\lim_{\epsilon \rightarrow 0} \frac{\Delta \Av{r_k(t)}}{\epsilon} = \partial_\epsilon \Av{r_k(t)}_\epsilon \Big\vert_{\epsilon = 0} .
L000427	\end{align}
L000428	Suppose that the perturbation vanishes, that is $\phi_q(t) = 0$ for all $q$, for $t < 0$.
L000429	Then, we can formally write
L000430	\begin{align}
L000431	\Av{r_k(t)}_\epsilon = \int d\Gamma \ r_k(t) \mathbb{P}_\epsilon(\Gamma) .
L000432	\end{align}
L000433	Here, $\Gamma = \lbrace\bm{x}(t')\rbrace_{t' \in [0,t]}$ is a trajectory of the system during the time-interval $[0,t]$ and $\mathbb{P}_\epsilon(\Gamma)$ is the probability of the trajectory in the perturbed system, starting from the steady state at $t = 0$.
L000434	Since the trajectory probability is positive, we can write
L000435	\begin{align}
L000436	\partial_\epsilon \Av{r_k(t)}_\epsilon \Big\vert_{\epsilon = 0} &= \int d\Gamma \ r_k(t) \partial_\epsilon \mathbb{P}_\epsilon(\Gamma) \Big\vert_{\epsilon = 0} = \int d\Gamma \ r_k(t) \partial_\epsilon \big(\ln \mathbb{P}_\epsilon(\Gamma) \big) \mathbb{P}_\epsilon(\Gamma) \Big\vert_{\epsilon = 0} \nn
L000437	& = \int d\Gamma \ r_k(t) \partial_\epsilon \big(\ln \mathbb{P}_\epsilon(\Gamma) \big) \Big\vert_{\epsilon = 0} \mathbb{P}_0(\Gamma) .
L000438	\end{align}
L000439	We define the trajectory-dependent quantity
L000440	\begin{align}
L000441	\partial_\epsilon \big(\ln \mathbb{P}_\epsilon(\Gamma) \big) \Big\vert_{\epsilon = 0} = Q(\Gamma) .
L000442	\end{align}
L000443	Since $\mathbb{P}_0(\Gamma)$ is the trajectory probability of the unperturbed steady-state system, we can write
L000444	\begin{align}
L000445	\partial_\epsilon \Av{r_k(t)}_\epsilon \Big\vert_{\epsilon = 0} = \Av{r_k(t) Q(\Gamma)}_\text{st} .
L000446	\end{align}
L000447	As shown in Ref.~\cite{Dechant2020}, the derivative of the logarithm of the path probability is given by
L000448	\begin{align}
L000449	\partial_\epsilon \big(\ln \mathbb{P}_\epsilon(\Gamma) \big) \Big\vert_{\epsilon = 0} = \frac{1}{2} \int_0^t dt' \ \sum_{q = 1}^Q \phi_q(t') \bm{y}_q(\bm{x}(t')) \bm{B}(\bm{x}(t'))^{-1} \sqrt{2 \bm{B}(\bm{x}(t'))} \cdot \bm{\xi}(t') \equiv \int_0^t dt' \ \sum_{q=1}^Q \psi_q(t') \phi_q(t'), \label{path-log}
L000450	\end{align}
L000451	which defines the \enquote{response observable}
L000452	\begin{align}
L000453	\psi_q(t) = \frac{1}{2} \bm{y}_q(\bm{x}(t)) \bm{B}(\bm{x}(t))^{-1} \sqrt{2 \bm{B}(\bm{x}(t))} \cdot \bm{\xi}(t) \label{response-observable} .
L000454	\end{align}
L000455	This allows us to express the linear response as
L000456	\begin{align}
L000457	\partial_\epsilon \Av{r_k(t)}_\epsilon \Big\vert_{\epsilon = 0} = \sum_{q = 1}^Q \int_0^t dt' \ \Av{r_k(t) \psi_q(t')}_\text{st} \phi_q(t') .
L000458	\end{align}
L000459	Since the steady state is time-translation invariant, we can define the response matrix
L000460	\begin{align}
L000461	R_{kq}(t-t') = \Av{r_k(t) \psi_q(t')}_\text{st} \label{response-correlation},
L000462	\end{align}
L000463	which results in the expression for the response
L000464	\begin{align}
L000465	\partial_\epsilon \Av{r_k(t)}_\epsilon \Big\vert_{\epsilon = 0} = \int_0^t dt' \ \sum_{q = 1}^Q R_{kq}(t-t') \phi_q(t') .
L000466	\end{align}
L000467	Thus, the response matrix quantifies the response of observable $k$ at time $t$ to perturbation $q$ at the earlier time $t'$.
L000468	\eqref{response-correlation} is the generalized fluctuation-dissipation theorem discussed in Refs.~\cite{Agarwal1972,Haenggi1982a,Marconi2008,Baiesi2009,Seifert2010a}.
L000469	It expresses the response in terms of a correlation function in the unperturbed steady state, at the expense that it involves the correlation of the observable $r_k(t)$ with the quantity $\psi_q(t)$, which is generally not directly measurable.
L000470	Since $\psi_q(t)$ involves an Ito-product with the noise, we obtain $R_{kq}(t-t') = 0$ for $t' > t$ due to the non-anticipating property of white noise, i.~e.~the noise at time $t'$ is independent of the dynamics at any earlier time $t$.
L000471	Using that, in the unperturbed system, we have from \eqref{langevin}
L000472	\begin{align}
L000473	\sqrt{2 \bm{B}(\bm{x}(t))} \cdot \bm{\xi}(t) = \dot{\bm{x}}(t) - \bm{a}(\bm{x}(t)),
L000474	\end{align}
L000475	we can further write the response observable as
L000476	\begin{align}
L000477	\psi_q(t) = \frac{1}{2} \bm{y}_q(\bm{x}(t)) \bm{B}(\bm{x}(t))^{-1} \cdot \big(\dot{\bm{x}}(t) - \bm{a}(\bm{x}(t))\big) .
L000478	\end{align}
L000479	Using Ito's lemma to transform the Ito-product into a Stratonovich product, this can be written as
L000480	\begin{align}
L000481	\psi_q(t) = - \frac{1}{2} \bm{y}_q(\bm{x}(t)) \bm{B}(\bm{x})^{-1} \bm{a}(\bm{x}(t)) + \frac{1}{2} \bm{y}_q(\bm{x}(t)) \bm{B}^{-1}(\bm{x}) \circ \dot{\bm{x}}(t) - \frac{1}{2} \text{tr} \Big( \bm{B}(\bm{x}(t)) \bm{J}_{\bm{B}^{-1} \bm{y}_q}(\bm{x}(t)) \Big) ,
L000482	\end{align}
L000483	where tr denotes the trace and $\bm{J}_{\bm{B}^{-1} \bm{y}_q}(\bm{x})$ is the Jacobian matrix of the vector field $\bm{B}(\bm{x})^{-1} \bm{y}_q(\bm{x})$.
L000484	Writing the last term explicitly in index notation, he have
L000485	\begin{align}
L000486	\text{tr} \Big( \bm{B}(\bm{x}) \bm{J}_{\bm{B}^{-1} \bm{y}_q}(\bm{x}) \Big)  = B_{jk}(\bm{x}) \partial_{x_j} \Big( \big(\bm{B}(\bm{x})^{-1} \big)_{k l} y_{q,l}(\bm{x}) \Big) ,
L000487	\end{align}
L000488	where the sum over repeated indices is implied.
L000489	Using the formula for the derivative of an inverse matrix,
L000490	\begin{align}
L000491	\partial_{x_j} \bm{B}(\bm{x})^{-1} = - \bm{B}(\bm{x})^{-1} \partial_{x_j} \bm{B}(\bm{x}) \bm{B}(\bm{x})^{-1},
L000492	\end{align}
L000493	we obtain
L000494	\begin{align}
L000495	\text{tr} \Big( \bm{B}(\bm{x}) \bm{J}_{\bm{B}^{-1} \bm{y}_q}(\bm{x}) \Big)  = B_{jk}(\bm{x}) \big(\bm{B}(\bm{x})^{-1} \big)_{kl} \partial_{x_j} y_{q,l} - B_{jk}(\bm{x}) \big(\bm{B}(\bm{x})^{-1} \big)_{km} \partial_{x_j} B_{mn}(\bm{x}) \big(\bm{B}(\bm{x})^{-1} \big)_{nl} y_{q,l}(\bm{x}) .
L000496	\end{align}
L000497	Canceling the matrix $\bm{B}(\bm{x})$ and its inverse, this simplifies to
L000498	\begin{align}
L000499	\text{tr} \Big( \bm{B}(\bm{x}) \bm{J}_{\bm{B}^{-1} \bm{y}_q}(\bm{x}) \Big) = \grad \bm{y}_q(\bm{x}) - \grad \bm{B}(\bm{x}) \bm{B}(\bm{x})^{-1} \bm{y}_q(\bm{x}) .
L000500	\end{align}
L000501	Recalling the definition of the steady-state local mean velocity \eqref{fpe-steady}, we obtain
L000502	\begin{align}
L000503	\psi_q(t) = - \frac{1}{2} \bigg( \bm{y}_q(\bm{x}(t)) \bm{B}(\bm{x}(t))^{-1} \bm{\nu}_\text{st}(\bm{x}(t)) + \frac{\grad \big(\bm{y}_q(\bm{x}(t)) p_\text{st}(\bm{x}(t)) \big)}{p_\text{st}(\bm{x}(t))} \bigg) + \frac{1}{2} \bm{y}_q(\bm{x}(t)) \bm{B}(\bm{x}(t))^{-1} \circ \dot{\bm{x}}(t) .
L000504	\end{align}
L000505	We see that this is of the same form as the observables $r_k(t)$ defined in \eqref{observable},
L000506	\begin{gather}
L000507	\psi_q(t) = \tilde{z}_q(\bm{x}(t)) + \tilde{\bm{w}}_q(\bm{x}(t)) \circ \dot{\bm{x}}(t) \qquad \text{with} \label{response-observable-2} \\
L000508	\tilde{z}_q(\bm{x}) = - \frac{1}{2} \bigg( \bm{y}_q(\bm{x}) \bm{B}(\bm{x})^{-1} \bm{\nu}_\text{st}(\bm{x}) + \frac{\grad \big(\bm{y}_q(\bm{x}) p_\text{st}(\bm{x}) \big)}{p_\text{st}(\bm{x})} \bigg) \qquad \text{and} \qquad \tilde{\bm{w}}_q(\bm{x}) = \frac{1}{2} \bm{B}(\bm{x})^{-1} \bm{y}_q(\bm{x}) . \n
L000509	\end{gather}
L000510	Thus, the \enquote{response observable}, while not directly measurable, as it requires knowledge about the diffusion matrix, steady-state probability density, and local mean velocity, is mathematically an observable of the same type as $r_k(t)$.
L000511	
L000512	\subsubsection{Fluctuation-response inequality}
L000513	We define the frequency-response matrix as the Fourier transform of the response matrix \eqref{response-correlation},
L000514	\begin{align}
L000515	\bmc{R}(\omega) = \int_0^\infty dt \ e^{i \omega t} \bm{R}(t),
L000516	\end{align}
L000517	where we used that the response matrix vanishes for $t < 0$.
L000518	Since, from \eqref{response-observable-2}, the quantities $\psi_q(t)$ are of the same type as $r_k(t)$, we can consider the power-spectral density matrix of the extended set ob observables $\lbrace r_1(t), \ldots, r_K(t), \psi_1(t), \ldots, \psi_Q(t) \rbrace$,
L000519	\begin{align}
L000520	\big(\mathbb{S}(\omega) \big)_{k,l} = \int_{-\infty}^\infty dt \ e^{i \omega t} \times \left\lbrace \begin{array}{ll}
L000521	\text{Cov}_\text{st}(r_k(t),z_l(0)) &\text{if} \; k,l \leq K \\[1ex]
L000522	\text{Cov}_\text{st}(r_k(t),\psi_l(0)) &\text{if} \; k \leq K, l \geq K+1 \\[1ex]
L000523	\text{Cov}_\text{st}(\psi_k(t),r_l(0)) &\text{if} \; l \leq K, k \geq K+1 \\[1ex]
L000524	\text{Cov}_\text{st}(\psi_k(t),\psi_l(0)) &\text{if} \; k,l \geq K+1 .
L000525	\end{array} \right.
L000526	\end{align}
L000527	From \eqref{response-correlation}, we identify the covariance between $r_k(t)$ and $\psi_q(0)$ as the $(k,q)$ entry of the response matrix and can thus write
L000528	\begin{align}
L000529	\mathbb{S}(\omega) = \begin{pmatrix} \bmc{S}(\omega) & \bmc{R}(\omega) \\ \bmc{R}(\omega)^\text{H} & \bm{\Psi}(\omega) \end{pmatrix} ,
L000530	\end{align}
L000531	where $\bm{\Psi}(\omega)$ is the Fourier transform of the covariance of the observables $\psi_q(t)$ and H denotes the Hermitian conjugate.
L000532	Note that $\Av{\psi_q}_\text{st} = 0$, which is apparent from \eqref{response-observable}.
L000533	From the latter, we also find
L000534	\begin{align}
L000535	\text{Cov}_\text{st}(\psi_q(t),\psi_r(0)) &= \Av{\psi_q(t) \psi_r(0)}_\text{st} \label{response-observable-correlation} \\
L000536	&= \frac{1}{4} \Av{\Big(\bm{y}_q(\bm{x}(t)) \bm{B}(\bm{x}(t))^{-1} \sqrt{2 \bm{B}(\bm{x}(t))} \cdot \bm{\xi}(t) \Big) \Big( \bm{y}_r(\bm{x}(0)) \bm{B}(\bm{x}(0))^{-1} \sqrt{2 \bm{B}(\bm{x}(0))} \cdot \bm{\xi}(0) \Big)}_\text{st}\nn
L000537	& = \frac{1}{2} \Av{\bm{y}_q \bm{B}^{-1} \bm{y}_r}_\text{st} \delta(t) \n,
L000538	\end{align}
L000539	which follows from the delta-correlated white noise.
L000540	Thus, the matrix $\bm{\Psi}(\omega)$ is independent of frequency,
L000541	\begin{align}
L000542	\Psi_{qr}(\omega) = \frac{1}{2} \Av{\bm{y}_q \bm{B}^{-1} \bm{y}_r}_\text{st}  = \mathcal{A}_{qr},
L000543	\end{align}
L000544	and we obtain
L000545	\begin{align}
L000546	\mathbb{S}(\omega) = \begin{pmatrix} \bmc{S}(\omega) & \bmc{R}(\omega) \\ \bmc{R}(\omega)^\text{H} & \bmc{A} \end{pmatrix} .
L000547	\end{align}
L000548	Since $\mathbb{S}(\omega)$ is a power spectral density matrix and thus Hermitian and positive definite, this implies that the Schur complements of its diagonal blocks are likewise positive definite,
L000549	\begin{align}
L000550	\bmc{S}(\omega) - \bmc{R}(\omega) \bmc{A}^{-1} \bmc{R}(\omega)^\text{H} \geq 0 \qquad \text{and} \qquad \bmc{A} - \bmc{R}(\omega)^\text{H} \bmc{S}(\omega)^{-1} \bmc{R}(\omega) \geq 0 . \label{fffri-2}
L000551	\end{align}
L000552	The second relation is precisely the fluctuation-response inequality (FRI), \eqref{fffri} of the main text,
L000553	\begin{align}
L000554	\bmc{R}(\omega)^\text{H} \bmc{S}(\omega)^{-1} \bmc{R}(\omega) \leq \bmc{A} . \label{app-fffri}
L000555	\end{align}
L000556	Note that the above derivation shows that this result is more general, in the sense that it also applies to Langevin equations with arbitrary, position-dependent diffusion matrices, e.~g.~for heat baths with different temperatures or spatial temperature profiles.
