L000577	\subsection{Underdamped Langevin dynamics} \label{sec-fffri-under}
L000578	We consider the underdamped Langevin equations for the positions $\bm{x}(t) \in \mathbb{R}^d$ and velocities $\bm{v}(t) \in \mathbb{R}^d$,
L000579	\begin{align}
L000580	\dot{\bm{x}}(t) = \bm{v}(t), \qquad \bm{m} \bm{v}(t) = - \bm{\gamma}(\bm{x}(t)) \bm{v}(t) + \bm{f}(\bm{x}(t),\bm{v}(t)) + \epsilon \sum_{q = 1}^Q \bm{g}_q(\bm{x}(t),\bm{v}(t)) \phi_q(t) + \sqrt{2 \bm{\gamma}(\bm{x}(t)) \bm{T}(\bm{x}(t))} \bm{\xi}(t) \label{app-langevin-under} .
L000581	\end{align}
L000582	Compared to \eqref{langevin-under}, we also allow for different mass, as well as non-isotropic and non-uniform friction and temperature.
L000583	Specifically, we assume that $\bm{m}$, $\bm{\gamma}(\bm{x})$ and $\bm{T}(\bm{x})$ are diagonal matrices with positive entries; since they are diagonal, they mutually commute.
L000584	We also allow the steady-state force, as well as the perturbation force, to depend on velocity, as in the case of magnetic fields.
L000585	Formally, we can write this as an equation of the form \eqref{langevin} by defining the phase-space coordinate $\bm{u}(t) = (\bm{x}(t),\bm{v}(t))$,
L000586	\begin{align}
L000587	\dot{\bm{u}}(t) = \bm{a}_u(\bm{u}(t)) + \epsilon \sum_{q = 1}^Q \bm{y}_u(\bm{u}(t)) \phi_q(t) + \sqrt{2 \bm{B}_u(\bm{u}(t))} \cdot \bm{\xi}_u(t) .
L000588	\end{align}
L000589	However, the specific form of \eqref{app-langevin-under} leads to two crucial differences:
L000590	First, the diffusion matrix
L000591	\begin{align}
L000592	\bm{B}_u(\bm{u}) = \begin{pmatrix} \bm{0} & \bm{0} \\ \bm{0} & \bm{m}^{-2} \bm{\gamma}(\bm{x}) \bm{T}(\bm{x}) \end{pmatrix}
L000593	\end{align}
L000594	is singular.
L000595	At first glance, this means that the change in the path probability \eqref{path-log}, which involves the inverse of the diffusion matrix, is ill-defined.
L000596	However, the second difference is that the perturbation force only acts on the equations for the velocity, which are associated with the non-singular components of the diffusion matrix.
L000597	As a consequence, the expression \eqref{path-log} remains valid when replacing the inverse of the diffusion matrix with the inverse of the velocity-block of the diffusion matrix.
L000598	
L000599	The remaining derivation proceeds then in the same way as in the overdamped case.
L000600	We define the observables,
L000601	\begin{align}
L000602	r_k(t) = z_k(\bm{x}(t),\bm{v}(t)) + \bm{w}_k(\bm{x}(t),\bm{v}(t)) \circ \dot{\bm{v}}(t) . \label{observable-under}
L000603	\end{align}
L000604	Since the velocities are now explicit configuration variables, it is sufficient to consider configuration-dependent observables with $\bm{w}_k = 0$ to reproduce \eqref{observable}.
L000605	The definition of the power-spectral density $\bmc{S}(\omega)$ \eqref{power-spectral-density} is completely analog to the overdamped case.
L000606	For the response of the observables, we obtain in analogy to \eqref{response-correlation}
L000607	\begin{align}
L000608	R_{kq}(t-t') = \Av{r_k(t) \psi_q(t')}_\text{st},
L000609	\end{align}
L000610	where the quantity $\psi_q(t)$ is now given by
L000611	\begin{align}
L000612	\psi_q(t) &= \frac{1}{2} \bm{g}_q(\bm{x}(t),\bm{v}(t)) \bm{\gamma}(\bm{x}(t))^{-1} \bm{T}(\bm{x}(t))^{-1}  \sqrt{2 \bm{\gamma}(\bm{x}(t)) \bm{T}(\bm{x}(t))} \cdot \bm{\xi}(t) \\
L000613	&= \frac{1}{2} \bm{g}_q(\bm{x}(t),\bm{v}(t)) \bm{\gamma}(\bm{x}(t))^{-1} \bm{T}(\bm{x}(t))^{-1} \cdot \Big( \bm{m} \dot{\bm{v}}(t) + \bm{\gamma}(\bm{x}(t)) \bm{v}(t) - \bm{f}(\bm{x}(t),\bm{v}(t))  \Big) . \n
L000614	\end{align}
L000615	Since the diffusion matrix is independent of $\bm{v}$, converting from the Ito- to the Stratonovich product now simply yields
L000616	\begin{align}
L000617	\psi_q(t) = \frac{1}{2} \bigg( \bm{g}_q(\bm{x}(t),\bm{v}(t)) & \bm{\gamma}(\bm{x}(t))^{-1} \bm{T}(\bm{x}(t))^{-1} \Big( \bm{\gamma}(\bm{x}(t)) \bm{v}(t) - \bm{f}(\bm{x}(t),\bm{v}(t)) \Big) - \bm{m}^{-1} \grad_v \bm{g}_q(\bm{x}(t),\bm{v}(t)) \bigg) \\
L000618	& + \frac{1}{2} \bm{g}_q(\bm{x}(t),\bm{v}(t)) \bm{\gamma}(\bm{x}(t))^{-1} \bm{T}(\bm{x}(t))^{-1} \circ \dot{\bm{v}}(t) \n .
L000619	\end{align}
L000620	This is again of the same type as \eqref{observable-under} and we can write the joint spectral density matrix of the observables $r_k(t)$ and the perturbation observables $\psi_q(t)$ as
L000621	\begin{align}
L000622	\mathbb{S}(\omega) = \begin{pmatrix} \bmc{S}(\omega) & \bmc{R}(\omega) \\ \bmc{R}(\omega)^\text{H} & \bmc{A} \end{pmatrix},
L000623	\end{align}
L000624	where the matrix $\bmc{A}$ is now given by
L000625	\begin{align}
L000626	\mathcal{A}_{qr} = \frac{1}{2} \Av{\bm{g}_q \bm{\gamma}^{-1} \bm{T}^{-1} \bm{g}_r}_\text{st} ,
L000627	\end{align}
L000628	Since \eqref{fffri-2} only depends on the positive-definiteness of the power spectrum, it also applies in the underdamped case and we still have \eqref{app-fffri},
L000629	\begin{align}
L000630	\bmc{R}(\omega)^\text{H} \bmc{S}(\omega)^{-1} \bmc{R}(\omega) \leq \bmc{A} \label{fffri-under} .
L000631	\end{align}
L000632	Interestingly, while the dynamics and thus the response and fluctuations depend on the masses, the matrix $\bmc{A}$ and thus the upper bound in the FRI are independent of $\bm{m}$.
L000633	
L000634	
