L000636	\subsection{Markov jump dynamics}  \label{sec-fffri-jump}
L000637	Whereas in the previous cases, the configuration of the system was determined by a set of continuous real-valued variables, we now consider the case of a discrete set of configurations $\alpha(t) \in \lbrace 1,\ldots,N \rbrace$.
L000638	The transitions between different configurations are described by non-negative rates $\Omega(\alpha \vert \beta,t)$; the probability of observing a transition to configuration $\alpha$ during the time-interval $[t,t+dt]$, provided that the system was in configuration $\beta$ at time $t$ is $\Omega(\alpha \vert \beta,t) dt$.
L000639	The conditional probability $p(\alpha,t \vert \gamma,0)$ of observing configuration $\alpha$ at time $t$ conditioned on being in configuration $\gamma$ at time $0$ is then determined by the master equation
L000640	\begin{align}
L000641	d_t p(\alpha,t \vert \gamma,0) = \sum_{\beta = 1}^N \Big( \Omega(\alpha \vert \beta,t) p(\beta,t \vert \gamma,0) - \Omega(\beta \vert \alpha,t) p(\alpha,t \vert \gamma,0) \Big) . \label{master}
L000642	\end{align}
L000643	We write the rates as ($\alpha \neq \beta$)
L000644	\begin{align}
L000645	\Omega_\epsilon(\alpha \vert \beta,t) = \Omega_0(\alpha \vert \beta) \exp \bigg( \epsilon \sum_{q = 1}^Q Y_q(\alpha \vert \beta) \phi_q(t) \bigg) \label{rates} ,
L000646	\end{align}
L000647	with the unperturbed rates $\Omega_0(\alpha \vert \beta) \geq 0$, which ensures that the rates remain positive in the presence of the perturbation.
L000648	For $\epsilon = 0$, the rates are time-independent and we assume that the probability relaxes to a steady state $p_\text{st}(\alpha)$, determined by
L000649	\begin{align}
L000650	0 = \sum_{\beta = 1}^N \Big( \Omega_0(\alpha \vert \beta) p_\text{st}(\beta) - \Omega_0(\beta \vert \alpha) p_\text{st}(\alpha) \Big).
L000651	\end{align}
L000652	We define the observables as
L000653	\begin{align}
L000654	r_k(t) = z_k(\alpha(t)) + \frac{1}{dt} w_k(\alpha(t+dt) \vert \alpha(t)) \label{observable-jump} ,
L000655	\end{align}
L000656	where $z_k(\alpha)$ is a configuration-dependent function and the transition-dependent term $w_k(\alpha \vert \beta)$ is non-zero only if $\alpha \neq \beta$.
L000657	The steady-state average of the observable is
L000658	\begin{align}
L000659	\Av{r_k}_\text{st} = \sum_\alpha z_k(\alpha) p_\text{st}(\alpha) + \sum_{\alpha,\beta; \alpha \neq \beta} w_k(\alpha \vert \beta) \Omega_0(\alpha \vert \beta) p_\text{st}(\beta) .
L000660	\end{align}
L000661	
L000662	The probability of a discretized trajectory during a time interval $[0,t]$, $\bar{\Gamma} = \lbrace \alpha(\theta dt) \rbrace_{\theta \in \lbrace 0,\ldots,M \rbrace}$, where $t = M dt$ can we written as
L000663	\begin{align}
L000664	\mathbb{P}_\epsilon(\bar{\Gamma}) = \prod_{\theta = 1}^M p_\epsilon\big(\alpha_\theta, \theta dt \vert \alpha_{\theta-1}, (\theta-1)dt \big) p_\text{st}(\alpha_0) ,
L000665	\end{align}
L000666	where we assume that the system is initially in the unperturbed steady state.
L000667	The logarithm of the path probability is then
L000668	\begin{align}
L000669	\ln \mathbb{P}_\epsilon(\bar{\Gamma}) = \sum_{\theta = 1}^M \ln p_\epsilon\big(\alpha_\theta, \theta dt \vert \alpha_{\theta-1}, (\theta-1)dt \big) + \ln p_\text{st}(\alpha_0) .
L000670	\end{align}
L000671	For a sufficiently short time-interval $dt$, the short-time transition is given by
L000672	\begin{align}
L000673	p_\epsilon\big(\alpha_\theta, \theta dt \vert \alpha_{\theta-1}, (\theta-1)dt \big) = \left\lbrace \begin{array}{ll}
L000674	1 - \sum_{\beta \neq \alpha_{\theta-1}} \Omega_\epsilon(\beta \vert \alpha_{\theta-1},(\theta - 1)dt) dt &\text{if} \; \alpha_\theta = \alpha_{\theta-1} \\[2ex]
L000675	\Omega_{\epsilon}(\alpha_\theta \vert \alpha_{\theta-1},(\theta - 1)dt) dt &\text{if} \; \alpha_\theta \neq \alpha_{\theta-1} .
L000676	\end{array}  \right.
L000677	\end{align}
L000678	The expression in the first line follows from the second line by conservation of probability.
L000679	Taking the logarithm and the derivative with respect to $\epsilon$ at $\epsilon = 0$, we obtain
L000680	\begin{align}
L000681	\partial_\epsilon \ln p_\epsilon\big(\alpha_\theta, \theta dt \vert \alpha_{\theta-1}, (\theta-1)dt \big) \Big\vert_{\epsilon = 0} = \left\lbrace \begin{array}{ll}
L000682	- \frac{ \sum_{\beta \neq \alpha_{\theta-1}} \Omega_0(\beta \vert \alpha_{\theta-1}) \sum_{q = 1}^Q Y_q(\beta \vert \alpha_{\theta-1}) \phi_q((\theta-1)dt) dt}{1 - \sum_{\beta \neq \alpha_{\theta-1}} \Omega_0(\beta \vert \alpha_{\theta-1},(\theta - 1)dt) dt} &\text{if} \; \alpha_\theta = \alpha_{\theta-1} \\[2ex]
L000683	\sum_{q = 1}^Q Y_q(\alpha_\theta \vert \alpha_{\theta-1}) \phi_q((\theta-1)dt) &\text{if} \; \alpha_\theta \neq \alpha_{\theta-1} .
L000684	\end{array}  \right.
L000685	\end{align}
L000686	Setting $Y_q(\alpha \vert \alpha) = 0$ and expanding for small $dt$, we can write the derivative of the trajectory probability as
L000687	\begin{gather}
L000688	\partial_\epsilon \ln \mathbb{P}_\epsilon(\bar{\Gamma}) \Big\vert_{\epsilon = 0} = \sum_{q = 1}^Q \sum_{\theta = 1}^M \bigg(\tilde{z}_q(\alpha_{\theta-1}) + \frac{1}{dt} \tilde{w}_q(\alpha_\theta \vert \alpha_{\theta-1})\bigg) \phi_q((\theta-1)dt) dt  \\
L000689	\text{with} \qquad \tilde{z}_q(\alpha) = - \sum_{\beta} \Omega_0(\beta \vert \alpha) Y_q(\beta \vert \alpha), \qquad \tilde{w}_k(\alpha \vert \beta) = Y_q(\alpha \vert \beta) \n .
L000690	\end{gather}
L000691	In the continuous-time limit, we obtain
L000692	\begin{align}
L000693	\partial_\epsilon \ln \mathbb{P}_\epsilon(\bar{\Gamma}) \Big\vert_{\epsilon = 0} = \sum_{q=1}^Q \int_0^t dt' \ \psi_q(t') \phi_q(t') \qquad
L000694	\text{with} \qquad \psi_q(t) = \tilde{z}_q(\alpha(t)) + \frac{1}{dt} \tilde{w}_q(\alpha(t+dt) \vert \alpha(t)) .
L000695	\end{align}
L000696	Just as in the Langevin case, we can thus define a set of response observables $\psi_q(t)$ of the same type as \eqref{observable-jump}, in terms of which we can write
L000697	\begin{align}
L000698	\partial_\epsilon \Av{r_k(t)}_\epsilon \Big\vert_{\epsilon = 0} = \sum_{q = 1}^Q \int_0^t dt' \ R_{kq}(t-t') \phi_q(t') \qquad \text{with} \qquad R_{kq}(t-t') = \Av{r_k(t) \psi_q(t')}_\text{st} .
L000699	\end{align}
L000700	Moreover, we have for the correlation between the response observables
L000701	\begin{align}
L000702	\Av{\psi_q(t) \psi_r(t')}_\text{st} = \Bigg\langle \bigg(\frac{1}{dt} &Y_q(\alpha(t+dt)\vert \alpha(t)) - \sum_{\beta} \Omega_0(\beta \vert \alpha(t)) Y_q(\beta \vert \alpha(t)) \bigg) \\
L000703	&\times \bigg(\frac{1}{dt} Y_r(\alpha(t'+dt)\vert \alpha(t')) - \sum_{\beta} \Omega_0(\beta \vert \alpha(t')) Y_r(\beta \vert \alpha(t')) \bigg) \Bigg\rangle_\text{st} \n .
L000704	\end{align}
L000705	Suppose that $t > t'+dt$,
L000706	In that case, since the dynamics is Markovian, the probability of being in configuration $\alpha(t)$ at time $t$ only depends on the last observed configuration $\alpha(t'+dt)$.
L000707	We can then consider the conditional average
L000708	\begin{align}
L000709	\Bigg\langle \bigg(\frac{1}{dt} &Y_q(\alpha(t+dt)\vert \alpha(t)) - \sum_{\beta} \Omega_0(\beta \vert \alpha(t)) Y_q(\beta \vert \alpha(t)) \bigg) \bigg\vert \alpha(t'+dt) = \tilde{\alpha} \Bigg\rangle_\text{st} \\
L000710	& = \sum_{\alpha_2,\alpha_1} \bigg( \frac{1}{dt} Y_q(\alpha_2 \vert \alpha_1) - \sum_{\beta} \Omega_0(\beta \vert \alpha_1) Y_q(\beta \vert \alpha_1) \bigg) p_0(\alpha_2, t+dt; \alpha_1,t \vert \tilde{\alpha}, t'+dt)  \nn
L000711	& = \sum_{\alpha_2,\alpha_1} \bigg( \frac{1}{dt} Y_q(\alpha_2 \vert \alpha_1) - \sum_{\beta} \Omega_0(\beta \vert \alpha_1) Y_q(\beta \vert \alpha_1) \bigg) p_0(\alpha_2, t+dt \vert \alpha_1,t) p_0(\alpha_1,t \vert \tilde{\alpha}, t'+dt) \n ,
L000712	\end{align}
L000713	where we once again used that the probability at time $t+dt$ only depends on the configuration at time $t$.
L000714	Since $Y_q(\alpha_2 \vert \alpha_1)$ is non-zero only for $\alpha_2 \neq \alpha_1$, we have  $p_0(\alpha_2, t+dt \vert \alpha_1,t) = \Omega_0(\alpha_2 \vert \alpha_1) dt$ and thus,
L000715	\begin{align}
L000716	\Bigg\langle \bigg(\frac{1}{dt} &Y_q(\alpha(t+dt)\vert \alpha(t)) - \sum_{\beta} \Omega_0(\beta \vert \alpha(t)) Y_q(\beta \vert \alpha(t)) \bigg) \bigg\vert \alpha(t'+dt) = \tilde{\alpha} \Bigg\rangle_\text{st} \\
L000717	& = \sum_{\alpha_1} \bigg( \sum_{\alpha_2} \Omega_0(\alpha_2 \vert \alpha_1) Y_q(\alpha_2 \vert \alpha_1)  - \sum_{\beta} \Omega_0(\beta \vert \alpha_1) Y_q(\beta \vert \alpha_1) \bigg) p_0(\alpha_1,t \vert \tilde{\alpha}, t'+dt) = 0 \n .
L000718	\end{align}
L000719	Thus, $\Av{\psi_q(t) \psi_r(t')}_\text{st} = 0$ for $t > t'$, and analogously for $t < t'$, and the only non-zero value is obtained for $t = t'$,
L000720	\begin{align}
L000721	\Av{\psi_q(t) \psi_r(t')}_\text{st} &= \Bigg\langle \bigg(\frac{1}{dt} Y_q(\alpha(t+dt)\vert \alpha(t)) - \sum_{\beta} \Omega_0(\beta \vert \alpha(t)) Y_q(\beta \vert \alpha(t)) \bigg) \\
L000722	&\hspace{2cm} \times \bigg(\frac{1}{dt} Y_r(\alpha(t+dt)\vert \alpha(t)) - \sum_{\beta} \Omega_0(\beta \vert \alpha(t)) Y_r(\beta \vert \alpha(t)) \bigg) \Bigg\rangle_\text{st} \nn
L000723	&= \sum_{\alpha_2} \sum_{\alpha_1} \bigg( \frac{1}{dt} Y_q(\alpha_2 \vert \alpha_1) - \sum_{\beta} \Omega_0(\beta \vert \alpha_1) Y_q(\beta \vert \alpha_1) \bigg) \bigg( \frac{1}{dt} Y_r(\alpha_2 \vert \alpha_1) - \sum_{\beta} \Omega_0(\beta \vert \alpha_1) Y_r(\beta \vert \alpha_1) \bigg)  \nn
L000724	&\hspace{3cm} \times p_0(\alpha_2, t+dt \vert \alpha_1,t) p_\text{st}(\alpha_1) \nn
L000725	&\simeq \frac{1}{dt} \sum_{\alpha_2} \sum_{\alpha_1} Y_q(\alpha_2 \vert \alpha_1) Y_r(\alpha_2 \vert \alpha_1) \Omega_0(\alpha_2 \vert \alpha_1) p_\text{st}(\alpha_1) + O(dt^0) , \n
L000726	\end{align}
L000727	where in the last line we only keep the leading-order term in $dt$.
L000728	In the continuous-time limit, we thus have
L000729	\begin{align}
L000730	\Av{\psi_q(t) \psi_r(t')}_\text{st} = \sum_{\alpha_2} \sum_{\alpha_1} Y_q(\alpha_2 \vert \alpha_1) Y_r(\alpha_2 \vert \alpha_1) \Omega_0(\alpha_2 \vert \alpha_1) p_\text{st}(\alpha_1) \delta(t-t') ,
L000731	\end{align}
L000732	in analogy to \eqref{response-observable-correlation}.
L000733	The delta-correlations of the response observable are a direct consequence of the Markovianity of the dynamics---white Gaussian noise in the Langevin case and white Poisson noise in the jump case.
L000734	
L000735	The remainder of the derivation proceeds analog to the Langevin case and we obtain
L000736	\begin{align}
L000737	\bmc{R}(\omega)^\text{H} \bmc{S}(\omega)^{-1} \bmc{R}(\omega) \leq \bmc{A} \qquad \text{with} \qquad \mathcal{A}_{qr} = \sum_{\alpha,\beta} Y_q(\alpha \vert \beta) Y_r(\alpha \vert \beta) \Omega_0(\alpha \vert \beta) p_\text{st}(\beta) . \label{fffri-jump}
L000738	\end{align}
L000739	Note that if the perturbations are either even or odd under time-reversal, $Y_q(\alpha \vert \beta) = \pm Y_q(\beta \vert \alpha)$, we can write the matrix $\bmc{A}$ as
L000740	\begin{align}
L000741	\mathcal{A}_{qr} = \sum_{\alpha,\beta} Y_q(\alpha \vert \beta) Y_r(\alpha \vert \beta) \mathcal{T}(\alpha, \beta)  \qquad \text{with} \qquad \mathcal{T}_\text{st}(\alpha, \beta) = \frac{1}{2} \big( \Omega_0(\alpha \vert \beta) p_\text{st}(\beta) + \Omega_0(\beta \vert \alpha) p_\text{st}(\alpha) \big) .
L000742	\end{align}
L000743	The quantity $\mathcal{T}_\text{st}(\alpha, \beta)$ is called the (steady-state) traffic between $\alpha$ and $\beta$; it measures the average rate of transitions between the configurations in either direction.
L000744	The sum of the traffic over all pairs of configurations is called the activity; thus, $\bmc{A}$ measures the activity in the unperturbed system weighted by the perturbations.
L000745	
L000746	A particular case of \eqref{rates} which assigns an energetic interpretation to the rates is
L000747	\begin{align}
L000748	\Omega_\epsilon(\alpha \vert \beta) = \Omega_0 \exp \bigg( - \frac{\beta}{2} \Big( B(\alpha,\beta) + U(\alpha) - U(\beta) - A(\alpha,\beta) + \epsilon G(\alpha,\beta) \phi(t) \Big) \bigg) .
L000749	\end{align}
L000750	Here, $\Omega_0$ is an overall rate and $\beta = 1/T$ is the inverse temperature.
L000751	The symmetric energy $B(\alpha,\beta) = B(\beta,\alpha)$ corresponds to an energy barrier between configurations $\alpha$ and $\beta$.
L000752	$U(\alpha)$ is the energy assigned to configuration $\alpha$ and $A(\alpha,\beta) = -A(\beta,\alpha)$ measures the energy supplied to the system by an external, non-conservative force in the transition from $\beta$ to $\alpha$.
L000753	In this case, the perturbation $G(\alpha,\beta)$ corresponds to changing either the heights of the barriers (if $G(\alpha,\beta) = G(\beta,\alpha)$), the energies of the configurations (if $G(\alpha,\beta) = V(\alpha) - V(\beta)$) or the energy supplied by the non-conservative force (if $G(\alpha,\beta)$ is antisymmetric but cannot be written as an energy difference).
L000754	
L000755	\section{Linear Langevin dynamics} \label{sec-linear}
L000756	
L000757	\subsection{Overdamped} \label{sec-linear-over}
L000758	Let us consider the special case of \eqref{langevin}
L000759	\begin{align}
L000760	\dot{\bm{x}}(t) = -\bm{A} \big(\bm{x}(t) - \bm{a} \big) + \epsilon \sum_{q=1}^Q \bm{y}_q \phi_q(t) + \sqrt{2 \bm{B}} \bm{\xi}(t). \label{langevin-linear-over}
L000761	\end{align}
L000762	Here, the force is linear in the coordinates, with a matrix $\bm{A}$ that has eigenvalues with positive real part to ensure that the steady state is stable.
L000763	The diffusion matrix $\bm{B}$ is constant and positive definite and the perturbations are constant vectors $\bm{y}_q$.
L000764	Since this equation is linear, the steady state probability density is Gaussian,
L000765	\begin{align}
L000766	p_\text{st}(\bm{x}) = \frac{1}{ \sqrt{(2 \pi)^D \det(\bm{\Xi}_\text{st})}} \exp \bigg( - \frac{1}{2} \big( \bm{x} - \bm{a} \big) \bm{\Xi}_\text{st}^{-1} \big( \bm{x} - \bm{a} \big) \bigg) ,
L000767	\end{align}
L000768	where the steady-state covariance matrix $(\bm{\Xi}_\text{st})_{jh} = \text{Cov}_\text{st}(x_j,x_h)$ is determined from the Lyapunov equation
L000769	\begin{align}
L000770	\bm{A} \bm{\Xi}_\text{st} + \bm{\Xi}_\text{st} \bm{A}^\text{T} = 2 \bm{B} . \label{lyapunov}
L000771	\end{align}
L000772	The system is in equilibrium if $\bm{A} \bm{B} = \bm{B} \bm{A}^\text{T}$, in which case $\bm{\Xi}_\text{st} = \bm{A}^{-1} \bm{B}$.
L000773	For given $\bm{x}(t')$, we can calculate the conditional average for $t > t'$ in the unperturbed system,
L000774	\begin{align}
L000775	\Av{\bm{x}(t) \vert \bm{x}(t')} = \bm{a} + e^{-\bm{A}(t-t')} \big( \bm{x}(t') - \bm{a} \big) .
L000776	\end{align}
L000777	Multiplying by $\bm{x}(t') - \bm{a}$ and averaging with respect to the steady-state density, we find
L000778	\begin{align}
L000779	\bm{C}(t-t') = \text{Cov}_\text{st}\big(\bm{x}(t),\bm{x}(t') \big) = \left\lbrace \begin{array}{ll}
L000780	e^{-\bm{A}(t-t')} \bm{\Xi}_\text{st} &\text{for} \; t \geq t' \\[1 ex]
L000781	\bm{\Xi}_\text{st} e^{-\bm{A}^\text{T}(t'-t)} & \text{for} \; t' > t .
L000782	\end{array}  \right.
L000783	\end{align}
L000784	Taking the Fourier transform, we obtain the power-spectral density matrix
L000785	\begin{align}
L000786	\bmc{S}(\omega) &= \big( \bm{A} - i \omega \bm{I}\big)^{-1} \bm{\Xi}_\text{st} + \bm{\Xi}_\text{st} \big( \bm{A}^\text{T} + i \omega \bm{I}\big)^{-1} \label{spectrum-linear-over} \\
L000787	&= \big( \bm{A}^2 + \omega^2 \bm{I}\big)^{-1} \bm{A} \bm{\Xi}_\text{st} + \bm{\Xi}_\text{st} \bm{A}^\text{T} \big( \bm{A}^{2,\text{T}} + \omega^2 \bm{I}\big)^{-1} + i \omega \Big( \big( \bm{A}^2 + \omega^2 \bm{I}\big)^{-1} \bm{\Xi}_\text{st} - \bm{\Xi}_\text{st} \big( \bm{A}^{2,\text{T}} + \omega^2 \bm{I}\big)^{-1} \Big) . \n
L000788	\end{align}
L000789	In equilibrium, the imaginary part vanishes, while the real part is the symmetric matrix
L000790	\begin{align}
L000791	\bmc{S}(\omega) &= \big( \bm{A}^2 + \omega^2 \bm{I}\big)^{-1} \bm{B} + \bm{B} \big( \bm{A}^{2} + \omega^2 \bm{I}\big)^{-1,\text{T}} .
L000792	\end{align}
L000793	In the presence of the perturbation, the average of $\bm{x}(t)$ is given by
L000794	\begin{align}
L000795	\Av{\bm{x}(t)}_\epsilon - \Av{\bm{x}}_\text{st} = \epsilon \sum_{q=1}^Q \int_0^t dt' \ e^{-\bm{A}(t-t')} \bm{y}_q \phi_q(t'),
L000796	\end{align}
L000797	and we can identify the response matrix of the positions for $t \geq 0$
L000798	\begin{align}
L000799	R_{jq}(t) = \big(e^{-\bm{A} t} \bm{y}_q \big)_j .
L000800	\end{align}
L000801	We choose $\bm{y}_q = y_0 \hat{\bm{e}}_q$ where $\hat{\bm{e}}_q$ is the unit vector in the direction of $x_q$ for $q = 1,\ldots,D$, which yields
L000802	\begin{align}
L000803	\bm{R}(t) = y_0 e^{-\bm{A} t} \qquad \Leftrightarrow \qquad \bmc{R}(\omega) = y_0 \big(\bm{A} - i \omega \bm{I} \big)^{-1} \label{response-linear-over} .
L000804	\end{align}
L000805	Combining \eqref{spectrum-linear-over} and \eqref{response-linear-over}, we find
L000806	\begin{align}
L000807	\bmc{R}(\omega)^\text{H} \bmc{S}(\omega)^{-1} \bmc{R}(\omega) &= y_0^2 \big(\bm{A}^\text{T} + i \omega \bm{I} \big)^{-1} \Big( \big( \bm{A} - i \omega \bm{I}\big)^{-1} \bm{\Xi}_\text{st} + \bm{\Xi}_\text{st} \big( \bm{A}^\text{T} + i \omega \bm{I}\big)^{-1} \Big)^{-1} \big(\bm{A} - i \omega \bm{I} \big)^{-1} \\
L000808	&= y_0^2 \Big( \bm{\Xi}_\text{st} \big( \bm{A}^\text{T} + i \omega \bm{I}\big) + \big( \bm{A} - i \omega \bm{I}\big) \bm{\Xi}_\text{st} \Big)^{-1} \nn
L000809	&= \frac{1}{2} y_0^2 \bm{B}^{-1} \n ,
L000810	\end{align}
L000811	where we used \eqref{lyapunov}.
L000812	This is precisely the matrix $\bmc{A}$ on the right-hand side of \eqref{app-fffri} for the perturbations $\bm{y}_q = y_0 \hat{\bm{e}}_q$,
L000813	\begin{align}
L000814	\mathcal{A}_{qr} = \frac{1}{2} y_0^2 \hat{\bm{e}}_q \bm{B}^{-1} \hat{\bm{e}}_r = \frac{1}{2} y_0^2 \big(\bm{B}^{-1}\big)_{qr} .
L000815	\end{align}
L000816	Thus, for linear dynamics, the inequality \eqref{app-fffri} turns into an equality, provided that we choose the degrees of freedom of the Langevin equation as the observables and that the perturbations are constant forces in the respective direction.
L000817	We also obtain
L000818	\begin{align}
L000819	\bmc{R}(\omega) \bmc{A}^{-1} \bmc{R}(\omega)^\text{H} &= 2 \big(\bm{A} - i \omega \bm{I} \big)^{-1} \bm{B} \big(\bm{A}^\text{T} + i \omega \bm{I} \big)^{-1} \label{response-equality-3} \\
L000820	&= \big(\bm{A} - i \omega \bm{I} \big)^{-1} \big( \bm{A} \bm{\Xi}_\text{st} + \bm{\Xi}_\text{st} \bm{A}^\text{T} \big) \big(\bm{A}^\text{T} + i \omega \bm{I} \big)^{-1} \nn
L000821	&= \big(\bm{A} - i \omega \bm{I} \big)^{-1} \Big( \big(\bm{A} - i \omega \bm{I} \big) \bm{\Xi}_\text{st} + \bm{\Xi}_\text{st} \big(\bm{A}^\text{T} + i \omega \bm{I} \big) \Big) \big(\bm{A}^\text{T} + i \omega \bm{I} \big)^{-1} \nn
L000822	&= \big( \bm{A} - i \omega \bm{I}\big)^{-1} \bm{\Xi}_\text{st} + \bm{\Xi}_\text{st} \big( \bm{A}^\text{T} + i \omega \bm{I}\big)^{-1} = \bmc{S}(\omega) \n ,
L000823	\end{align}
L000824	so that the first inequality in \eqref{fffri-2} is likewise an equality.
L000825	More generally, we consider observables that are linear combinations of the positions, $\bm{z}(t) = \bmc{Z} \bm{x}(t)$, where $\bmc{Z} \in \mathbb{R}^{K \times D}$.
L000826	For general perturbations $\bm{y}_q$, we also define the matrix $\bmc{Y} \in \mathbb{R}^{D \times Q}$ that has $\bm{y}_q$ as its $q$-th column.
L000827	Then, the corresponding power-spectral and response matrices are given by
L000828	\begin{align}
L000829	\bmc{S}(\omega) = \bmc{Z} \big( \bm{A} - i \omega \bm{I}\big)^{-1} \bm{\Xi}_\text{st} + \bm{\Xi}_\text{st} \big( \bm{A}^\text{T} + i \omega \bm{I}\big)^{-1} \bmc{Z}^\text{T}, \qquad \bmc{R}(\omega) = \bmc{Z} \big(\bm{A} - i \omega \bm{I} \big)^{-1} \bmc{Y}, \qquad \bmc{A} = \frac{1}{2} \bmc{Y}^\text{T} \bm{B}^{-1} \bmc{Y} .
L000830	\end{align}
L000831	Comparing this to the above, we find that, if $K = D$ and $\bmc{Z}$ is invertible, then
L000832	\begin{align}
L000833	\bmc{R}(\omega)^\text{H} \bmc{S}(\omega)^{-1} \bmc{R}(\omega) = \bmc{A},
L000834	\end{align}
L000835	while if $Q = D$ and $\bmc{Y}$ is invertible, then
L000836	\begin{align}
L000837	\bmc{R}(\omega) \bmc{A}^{-1} \bmc{R}(\omega)^\text{H} = \bmc{S}(\omega) .
L000838	\end{align}
L000839	Intuitively, if $\bmc{Z}$ is invertible, this means that the observables contain all information about the positions of the system, and measuring their responses and joint fluctuations can recover the magnitude of arbitrary perturbations that is characterized by the matrix $\bmc{A}$.
L000840	On the other hand, if $\bmc{Y}$ is invertible, the perturbations can reproduce any constant-in-space force and we can use them to reconstruct the fluctuations of arbitrary observables.
L000841	We stress that these results are valid independent of whether the system is in equilibrium or not; rather, they only rely on the linearity of the dynamics.
L000842	\eqref{linear-identity} of the main text is recovered for $\bm{A} = \frac{1}{\gamma} \bm{K}$, $\bm{B} = \frac{T}{\gamma} \bm{I}$ and $\bmc{Y} = \frac{1}{\gamma} \bmc{G}$, where $\bm{K}$ has the dimensions of a spring constant and $\bmc{G}$ of a force.
L000843	
L000844	\subsection{Underdamped} \label{sec-linear-under}
L000845	Next, we consider the linear underdamped equations
L000846	\begin{align}
L000847	\dot{\bm{x}}(t) = \bm{v}(t), \qquad \bm{m} \dot{\bm{v}}(t) = - \bm{\gamma} \bm{v}(t) - \bm{K} \big(\bm{x}(t) - \bm{a} \big) + \epsilon \sum_{q=1}^Q \bm{y}_q \phi_q(t) + \sqrt{2 \bm{\gamma} \bm{T}} \bm{\xi}(t),
L000848	\end{align}
L000849	where $\bm{m}$, $\bm{\gamma}$ and $\bm{T}$ are diagonal matrices with positive entries and $\bm{K}$ is a matrix whose eigenvalues have positive real parts.
L000850	As in Section \ref{sec-fffri-under}, we can formally write this as a linear overdamped equation with singular diffusion matrix by introducing the phase-space variable $\bm{u}(t) = (\bm{x}(t),\bm{v}(t))$,
L000851	\begin{gather}
L000852	\dot{\bm{u}}(t) = - \bm{A}_u \big( \bm{u}(t) - \bm{a}_u \big) + \epsilon \sum_{q=1}^Q \bm{y}_{u,q} \phi_q(t) + \sqrt{2 \bm{B}_u} \bm{\xi}(t) \qquad \text{with} \\
L000853	\bm{A}_u = \begin{pmatrix} \bm{0} & - \bm{I} \\ \bm{m}^{-1} \bm{K} & \bm{m}^{-1} \bm{\gamma} \end{pmatrix}, \qquad \bm{B}_u = \begin{pmatrix} \bm{0} & \bm{0} \\ \bm{0} & \bm{m}^{-2} \bm{\gamma} \bm{T} \end{pmatrix}, \qquad \bm{a}_u = \begin{pmatrix} \bm{a} \\ \bm{0} \end{pmatrix}, \qquad \bm{y}_{u,q} = \begin{pmatrix} \bm{0} \\ \bm{m}^{-1} \bm{y}_q \end{pmatrix} \n .
L000854	\end{gather}
L000855	In analogy to \eqref{spectrum-linear-over}, the power-spectral density matrix of the phase-space variables is given by
L000856	\begin{align}
L000857	\bmc{S}_u(\omega) = \big( \bm{A}_u - i \omega \bm{I}\big)^{-1} \bm{\Xi}_{u,\text{st}} + \bm{\Xi}_{u,\text{st}} \big( \bm{A}_u^\text{T} + i \omega \bm{I}\big)^{-1} \label{spectral-linear-under}.
L000858	\end{align}
L000859	From this, we can obtain the power-spectral density of the position degrees of freedom as the upper left block,
L000860	\begin{align}
L000861	\bmc{S}_x(\omega) = \big(\bmc{S}_u(\omega) \big)_{xx}
L000862	\end{align}
L000863	Since the perturbations only act on the equation for $\bm{v}$, we further have
L000864	\begin{align}
L000865	\bmc{R}_u(\omega) = \begin{pmatrix} \big(( \bm{A}_u - i \omega \bm{I})^{-1} \big)_{xv} \bm{m}^{-1} \bmc{Y} \\ \big(( \bm{A}_u - i \omega \bm{I})^{-1} \big)_{vv} \bm{m}^{-1} \bmc{Y}  \end{pmatrix}, \label{response-linear-under}
L000866	\end{align}
L000867	where, as in the overdamped case the matrix $\bmc{Y}$ has $\bm{y}_q$ as its $q$-th column.
L000868	The first component is the response $\bmc{R}_x(\omega)$ of the position degrees of freedom.
L000869	To proceed, we note that, due to the deterministic relation $\dot{\bm{x}}(t) = \bm{v}(t)$, which, in the Fourier domain becomes $-i \omega \hat{\bm{x}}(\omega) = \hat{\bm{v}}(\omega)$, the velocity and position components of $\bmc{S}_u(\omega)$ and $\bmc{R}_u(\omega)$ are related to each other by
L000870	\begin{align}
L000871	\big(\bmc{S}_u(\omega) \big)_{vv} = \omega^2 \big(\bmc{S}_u(\omega) \big)_{xx}, \qquad \big(\bmc{S}_u(\omega) \big)_{vx} = -i \omega \big(\bmc{S}_u(\omega) \big)_{xx},   \qquad \big( \bmc{R}_u(\omega) \big)_v = - i \omega \big( \bmc{R}_u(\omega) \big)_x .
L000872	\end{align}
L000873	Thus, it is sufficient to determine the fluctuations and response of either the position or the velocity; in the following, we will focus on the velocity.
L000874	We can evaluate this further by expressing the inverse of the matrix $\bm{A}_u - i \omega \bm{I}$ in terms of its blocks,
L000875	\begin{align}
L000876	\big(\bm{A}_u - i \omega \bm{I} \big)^{-1} = \begin{pmatrix}
L000877	\big( ( \bm{\gamma} - i \omega \bm{m} )^{-1} \bm{K} - i \omega \bm{I} \big)^{-1}
L000878	& \big( \bm{m}^{-1} \bm{K} - i \omega \bm{m}^{-1} (\bm{\gamma} - i \omega \bm{m}) \big)^{-1} \\
L000879	- \frac{i}{\omega} \big( -(i \omega \bm{m})^{-1} \bm{K} + \bm{m}^{-1}(\bm{\gamma} - i \omega \bm{m}) \big)^{-1} \bm{m}^{-1} \bm{K}
L000880	& \big( -(i \omega \bm{m})^{-1} \bm{K} + \bm{m}^{-1}(\bm{\gamma} - i \omega \bm{m}) \big)^{-1}  \end{pmatrix},
L000881	\end{align}
L000882	which results in
L000883	\begin{align}
L000884	\bmc{R}_v(\omega) = - i \omega \big( \bm{m}^{-1} \bm{K} - i \omega \bm{m}^{-1} (\bm{\gamma} - i \omega \bm{m}) \big)^{-1} \bm{m}^{-1} \bmc{Y} .
L000885	\end{align}
L000886	The matrix $\bmc{A}$ follows directly from \eqref{fffri-under},
L000887	\begin{align}
L000888	\bmc{A} = \frac{1}{2} \bmc{Y}^\text{T} \big(\bm{\gamma} \bm{T}\big)^{-1} \bmc{Y} .
L000889	\end{align}
L000890	If $\bmc{Y}$ is invertible, then
L000891	\begin{align}
L000892	\bmc{R}_v(\omega) \bmc{A}^{-1} \bmc{R}_v(\omega)^\text{H} = 2 \omega^2 \big( \bm{m}^{-1} \bm{K} - i \omega \bm{m}^{-1} (\bm{\gamma} - i \omega \bm{m}) \big)^{-1} \bm{m}^{-1} \bm{\gamma} \bm{T} \bm{m}^{-1} \big(  \bm{K}^\text{T} \bm{m}^{-1} + i \omega \bm{m}^{-1} (\bm{\gamma} + i \omega \bm{m}) \big)^{-1} \label{response-equality-1} .
L000893	\end{align}
L000894	We want to show that this is the same as the velocity component of the spectral density matrix,
L000895	\begin{align}
L000896	\bmc{S}_v(\omega) &= \big(\bm{m}^{-1} \bm{K} - i \omega \bm{m}^{-1}(\bm{\gamma} - i \omega \bm{m}) \big)^{-1} \big( - i \omega \bm{\Xi}_{vv,\text{st}} - \bm{m}^{-1} \bm{K} \bm{\Xi}_{xv,\text{st}} \big) \label{response-equality-2} \\
L000897	&\qquad + \big(i \omega \bm{\Xi}_{vv,\text{st}} - \bm{\Xi}_{vx,\text{st}} \bm{K}^\text{T} \bm{m}^{-1} \big) \big( \bm{K}^\text{T} \bm{m}^{-1}  + i \omega \bm{m}^{-1}(\bm{\gamma} + i \omega \bm{m}) \big)^{-1} \nn
L000898	&= \big(\bm{m}^{-1} \bm{K} - i \omega \bm{m}^{-1}(\bm{\gamma} - i \omega \bm{m}) \big)^{-1} \nn
L000899	&\qquad \times \bigg[ \big( - i \omega \bm{\Xi}_{vv,\text{st}} - \bm{m}^{-1} \bm{K} \bm{\Xi}_{xv,\text{st}} \big) \big( \bm{K}^\text{T} \bm{m}^{-1}  + i \omega \bm{m}^{-1}(\bm{\gamma} + i \omega \bm{m}) \big) \nn
L000900	&\qquad \qquad + \big(\bm{m}^{-1} \bm{K} - i \omega \bm{m}^{-1}(\bm{\gamma} - i \omega \bm{m}) \big) \big(i \omega \bm{\Xi}_{vv,\text{st}} - \bm{\Xi}_{vx,\text{st}} \bm{K}^\text{T} \bm{m}^{-1} \big) \bigg] \nn
L000901	&\qquad \times \big( \bm{K}^\text{T} \bm{m}^{-1}  + i \omega \bm{m}^{-1}(\bm{\gamma} + i \omega \bm{m}) \big)^{-1} . \n
L000902	\end{align}
L000903	Evaluating the term in square brackets, we find
L000904	\begin{align}
L000905	\bigg[ \ldots \bigg] &= -i \omega \Big( \bm{m}^{-1} \bm{K} \big( -\bm{\Xi}_{vv,\text{st}} + \bm{\Xi}_{xv} \bm{m}^{-1} \bm{\gamma} \big) - \big( -\bm{\Xi}_{vv,\text{st}} + \bm{\gamma}  \bm{m}^{-1} \bm{\Xi}_{xv} \big) \bm{K}^\text{T} \bm{m}^{-1} \Big) \label{brackets-term} \\
L000906	& \qquad + \omega^2 \Big( \bm{m}^{-1} \bm{\gamma} \bm{\Xi}_{vv,\text{st}} + \bm{\Xi}_{vv,\text{st}} \bm{\gamma} \bm{m}^{-1} + \bm{m}^{-1} \bm{K} \bm{\Xi}_{xv} + \bm{\Xi}_{vx,\text{st}} \bm{m}^{-1} \Big) - \bm{m}^{-1} \bm{K} \big( \bm{\Xi}_{xv,\text{st}} + \bm{\Xi}_{vx,\text{st}} \big) \bm{K}^\text{T} \bm{m}^{-1} \n .
L000907	\end{align}
L000908	
L000909	
L000910	
L000911	
L000912	We note that the phase-space covariance matrix $\bm{\Xi}_{u,\text{st}}$ is determined from the Lyapunov equation
L000913	\begin{align}
L000914	\bm{A}_u \bm{\Xi}_{u,\text{st}} + \bm{\Xi}_{u,\text{st}} \bm{A}_u^\text{T} = 2 \bm{B}_u ,
L000915	\end{align}
L000916	which we can write in block-wise form as
L000917	\begin{align}
L000918	&\begin{pmatrix}
L000919	- \bm{\Xi}_{vx,\text{st}} - \bm{\Xi}_{xv,\text{st}} & - \bm{\Xi}_{vv,\text{st}}  + \bm{\Xi}_{xv,\text{st}} \bm{m}^{-1} \bm{\gamma} + \bm{\Xi}_{xx,\text{st}} \bm{K}^\text{T} \bm{m}^{-1} \\
L000920	- \bm{\Xi}_{vv,\text{st}} + \bm{m}^{-1} \bm{\gamma} \bm{\Xi}_{vx,\text{st}} + \bm{m}^{-1} \bm{K} \bm{\Xi}_{xx,\text{st}}  & \bm{m}^{-1} \bm{K} \bm{\Xi}_{xv,\text{st}} + \bm{\Xi}_{vx,\text{st}} \bm{K}^\text{T} \bm{m}^{-1} + \bm{m}^{-1} \bm{\gamma} \bm{\Xi}_{vv,\text{st}} + \bm{\Xi}_{vv,\text{st}} \bm{\gamma} \bm{m}^{-1}
L000921	\end{pmatrix}  \nn
L000922	&\hspace{2cm} = \begin{pmatrix}
L000923	\bm{0} & \bm{0} \\ \bm{0} & 2 \bm{m}^{-2} \bm{\gamma} \bm{T}
L000924	\end{pmatrix} . \label{lyapunov-under}
L000925	\end{align}
L000926	From the $xx$-component, we find $\bm{\Xi}_{vx,\text{st}} = - \bm{\Xi}_{xv,\text{st}}$.
L000927	Inserting the $xv$ and $vx$ components into \eqref{brackets-term}, we obtain
L000928	\begin{align}
L000929	\bigg[ \ldots \bigg] &= i \omega \Big( \bm{m}^{-1} \bm{K} \bm{\Xi}_{xx,\text{st}} \bm{K}^\text{T} \bm{m}^{-1} - \bm{m}^{-1} \bm{K} \bm{\Xi}_{xx,\text{st}} \bm{K}^\text{T} \bm{m}^{-1} \Big) \label{brackets-term-2} \\
L000930	& \qquad + \omega^2 \Big( \bm{m}^{-1} \bm{\gamma} \bm{\Xi}_{vv,\text{st}} + \bm{\Xi}_{vv,\text{st}} \bm{\gamma} \bm{m}^{-1} + \bm{m}^{-1} \bm{K} \bm{\Xi}_{xv} + \bm{\Xi}_{vx,\text{st}} \bm{m}^{-1} \Big) \nn
L000931	&= \omega^2 \Big( \bm{m}^{-1} \bm{\gamma} \bm{\Xi}_{vv,\text{st}} + \bm{\Xi}_{vv,\text{st}} \bm{\gamma} \bm{m}^{-1} + \bm{m}^{-1} \bm{K} \bm{\Xi}_{xv} + \bm{\Xi}_{vx,\text{st}} \bm{m}^{-1} \Big) \n  .
L000932	\end{align}
L000933	Inserting the $vv$-component into \eqref{response-equality-1}, we obtain
L000934	\begin{align}
L000935	\bmc{R}_v(\omega) &\bmc{A}^{-1} \bmc{R}_v(\omega)^\text{H} = \omega^2 \big( \bm{m}^{-1} \bm{K} - i \omega \bm{m}^{-1} (\bm{\gamma} - i \omega \bm{m})^{-1} \big)^{-1} \\
L000936	&\times \big( \bm{m}^{-1} \bm{K} \bm{\Xi}_{xv,\text{st}} + \bm{\Xi}_{vx,\text{st}} \bm{K}^\text{T} \bm{m}^{-1} + \bm{m}^{-1} \bm{\gamma} \bm{\Xi}_{vv,\text{st}} + \bm{\Xi}_{vv,\text{st}} \bm{\gamma} \bm{m}^{-1} \big) \big(  \bm{K}^\text{T} \bm{m}^{-1} + i \omega \bm{m}^{-1} (\bm{\gamma} + i \omega \bm{m})^{-1} \big)^{-1} . \n
L000937	\end{align}
L000938	Comparing this to \eqref{response-equality-2}, we indeed find
L000939	\begin{align}
L000940	\bmc{R}_v(\omega) \bmc{A}^{-1} \bmc{R}_v(\omega)^\text{H} = \bmc{S}_v(\omega) ,
L000941	\end{align}
L000942	and thus equality in the first equation of \eqref{fffri-2}.
L000943	Due to the one-to-one relation between $\bm{x}(t)$ and $\bm{v}(t)$, this translates into the same relation for the position degrees of freedom,
L000944	\begin{align}
L000945	\bmc{R}_x(\omega) \bmc{A}^{-1} \bmc{R}_x(\omega)^\text{H} = \bmc{S}_x(\omega) .
L000946	\end{align}
L000947	Finally, let us compute
L000948	\begin{align}
L000949	\bmc{R}_v&(\omega)^\text{H} \bmc{S}_v(\omega)^{-1} \bmc{R}_v(\omega) = \omega^2 \bmc{Y}^\text{T} \bm{m}^{-1} \big(  \bm{K}^\text{T} \bm{m}^{-1} + i \omega \bm{m}^{-1} (\bm{\gamma} + i \omega \bm{m}) \big)^{-1} \\
L000950	&\times \bigg( \omega^2 \big(\bm{m}^{-1} \bm{K} - i \omega \bm{m}^{-1}(\bm{\gamma} - i \omega \bm{m}) \big)^{-1}  \Big( \bm{m}^{-1} \bm{\gamma} \bm{\Xi}_{vv,\text{st}} + \bm{\Xi}_{vv,\text{st}} \bm{\gamma} \bm{m}^{-1} + \bm{m}^{-1} \bm{K} \bm{\Xi}_{xv} + \bm{\Xi}_{vx,\text{st}} \bm{m}^{-1} \Big) \nn
L000951	&\qquad \times \big( \bm{K}^\text{T} \bm{m}^{-1}  + i \omega \bm{m}^{-1}(\bm{\gamma} + i \omega \bm{m}) \big)^{-1} \bigg)^{-1} \big( \bm{m}^{-1} \bm{K} - i \omega \bm{m}^{-1} (\bm{\gamma} - i \omega \bm{m}) \big)^{-1} \bm{m}^{-1} \bmc{Y} \n,
L000952	\end{align}
L000953	where we used \eqref{response-equality-2} and \eqref{brackets-term-2} to express the spectral density matrix.
L000954	Again using the $vv$-component of \eqref{lyapunov-under}, we obtain
L000955	\begin{align}
L000956	\bmc{R}_v(\omega)^\text{H} \bmc{S}_v(\omega)^{-1} \bmc{R}_v(\omega) = \bmc{Y}^\text{T} \bm{m}^{-1} \big( 2 \bm{m}^{-2} \bm{\gamma} \bm{T} \big)^{-1} \bm{m}^{-1} \bmc{Y} = \frac{1}{2} \bmc{Y}^\text{T} \big( \bm{\gamma} \bm{T} \big)^{-1} \bmc{Y} = \bmc{A},
L000957	\end{align}
L000958	and thus equality in the second equation of \eqref{fffri-2}.
L000959	This implies the same relation for the position degrees of freedom
L000960	\begin{align}
L000961	\bmc{R}_x(\omega)^\text{H} \bmc{S}_x(\omega)^{-1} \bmc{R}_x(\omega) = \bmc{A} .
L000962	\end{align}
L000963	For more general linear observables $\bm{z} = \bmc{Z} \bm{x}$ or $\bm{z} = \bmc{Z} \bm{v}$, the same relation holds if $\bmc{Z}$ is invertible.
L000964	
L000965	\section{Local perturbations}
L000966	
L000967	
L000968	Let us return to the overdamped equation \eqref{langevin-linear-over} and divide the degrees of freedom into two disjoint subsets $\bm{x}(t) = (\bm{x}_a(t),\bm{x}_p(t))$.
L000969	We assume that the diffusion matrix is block-diagonal
L000970	\begin{align}
L000971	\bm{B} = \begin{pmatrix} \bm{B}_a & \bm{0} \\ \bm{0} & \bm{B}_p \end{pmatrix}
L000972	\end{align}
L000973	We consider the case where the perturbation only acts on the \enquote{active} degrees of freedom $\bm{x}_a$, that is, $\bm{y}_q$ has non-zero entries only on the $\bm{x}_a$ directions.
L000974	We also measure the response and fluctuations of the active degrees of freedom.
L000975	Writing the coupling matrix in block form
L000976	\begin{align}
L000977	\bm{A} = \begin{pmatrix} \bm{A}_{aa} & \bm{A}_{ap} \\ \bm{A}_{pa} & \bm{A}_{pp} \end{pmatrix},
L000978	\end{align}
L000979	we can write the response matrix as
L000980	\begin{align}
L000981	\bmc{R}_{a}(\omega) = \Big( \bm{A}_{aa} - i \omega \bm{I} - \bm{A}_{ap} \big( \bm{A}_{pp} - i \omega \bm{I} \big)^{-1} \bm{A}_{pa} \Big)^{-1} \bmc{Y} \equiv \bmc{Q}_{aa}(\omega) \bmc{Y}  \label{response-block-inverse}.
L000982	\end{align}
L000983	On the other hand, the $aa$ component of the power-spectral density matrix can be written as (see \eqref{response-equality-3})
L000984	\begin{align}
L000985	\bmc{S}_{aa}(\omega) &= 2 \big(( \bm{A} - i \omega \bm{I} )^{-1} \big)_{aa} \bm{B}_a \big(( \bm{A}^\text{T} + i \omega \bm{I} )^{-1} \big)_{aa} + 2 \big(( \bm{A} - i \omega \bm{I} )^{-1} \big)_{ap} \bm{B}_p \big(( \bm{A}^\text{T} + i \omega \bm{I} )^{-1} \big)_{pa} \\
L000986	&= 2 \bmc{Q}_{aa}(\omega) \Big( \bm{B}_a + \bm{A}_{ap} \big(\bm{A}_{pp} - i \omega \bm{I} \big)^{-1} \bm{B}_p \big(\bm{A}_{pp}^\text{T} + i \omega \bm{I} \big)^{-1} \bm{A}_{ap}^\text{T} \Big) \bmc{Q}_{aa}(\omega)^\text{H} \n .
L000987	\end{align}
L000988	We then obtain
L000989	\begin{align}
L000990	\bmc{R}_a(\omega)^\text{H} \bmc{S}_{aa}(\omega)^{-1} \bmc{R}_a(\omega) = \frac{1}{2} \bmc{Y}^\text{T} \Big( \bm{B}_a + \bm{A}_{ap} \big(\bm{A}_{pp} - i \omega \bm{I} \big)^{-1} \bm{B}_p \big(\bm{A}_{pp}^\text{T} + i \omega \bm{I} \big)^{-1} \bm{A}_{ap}^\text{T} \Big)^{-1} \bmc{Y} \label{response-equality-4} .
L000991	\end{align}
L000992	The inequality \eqref{app-fffri} follows by noting that the second term in the expression in parentheses is positive definite and thus
L000993	\begin{align}
L000994	\frac{1}{2} \bmc{Y}^\text{T} \Big( \bm{B}_a + \bm{A}_{ap} \big(\bm{A}_{pp} - i \omega \bm{I} \big)^{-1} \bm{B}_p \big(\bm{A}_{pp}^\text{T} + i \omega \bm{I} \big)^{-1} \bm{A}_{ap}^\text{T} \Big)^{-1} \bmc{Y} \leq \frac{1}{2} \bmc{Y}^\text{T} \bm{B}_a^{-1} \bmc{Y} = \bmc{A} .
L000995	\end{align}
L000996	More explicitly, we have from the Woodbury matrix identity
L000997	\begin{align}
L000998	\Big( &\bm{B}_a + \bm{A}_{ap} \big(\bm{A}_{pp} - i \omega \bm{I} \big)^{-1} \bm{B}_p \big(\bm{A}_{pp}^\text{T} + i \omega \bm{I} \big)^{-1} \bm{A}_{ap}^\text{T} \Big)^{-1} \label{woodbury} \\
L000999	&= \bm{B}_a^{-1} - \bm{B}_a^{-1} \bm{A}_{ap} \big(\bm{A}_{pp} - i \omega \bm{I} \big)^{-1} \Big( \bm{B}_p^{-1} + \big(\bm{A}_{pp}^\text{T} + i \omega \bm{I} \big)^{-1} \bm{A}_{ap}^\text{T} \bm{B}_a^{-1} \bm{A}_{ap}\big(\bm{A}_{pp} - i \omega \bm{I} \big)^{-1} \Big)^{-1} \big(\bm{A}_{pp}^\text{T} + i \omega \bm{I} \big)^{-1} \bm{A}_{ap}^\text{T} \bm{B}_a^{-1} \nn
L001000	&= \bm{B}_a^{-1} - \bm{B}_a^{-1} \bm{A}_{ap} \Big( \bm{A}_{ap}^\text{T} \bm{B}_a^{-1} \bm{A}_{ap} + \big(\bm{A}_{pp}^\text{T} + i \omega \bm{I} \big) \bm{B}_p^{-1} \big(\bm{A}_{pp} - i \omega \bm{I} \big) \Big)^{-1}  \bm{A}_{ap}^\text{T} \bm{B}_a^{-1}  . \n
L001001	\end{align}
L001002	
L001003	\begin{figure*}
L001004	\includegraphics[width=0.4\textwidth]{a-partition.png}
L001005	\hspace{1cm}
L001006	\includegraphics[width=0.4\textwidth]{b-partition.png}
L001007	\caption{The structure of the coupling matrix $\bm{A}$ (left) and diffusion matrix $\bm{B}$ (right). The perturbed degrees of freedom $a^*$ (red) and their neighbors $N(a^*)$ (yellow) are the measured degrees of freedom $a$ (green). Since all other degrees of freedom $p$ (white) are not connected to $a^*$, the corresponding elements of the coupling matrix $\bm{A}$ are zero. For the diffusion matrix, we assume a block-diagonal structure between the perturbed degrees of freedom $a^*$, their neighbors $N(a^*)$ and the remaining degrees of freedom $p$.}
L001008	\label{fig-partition}
L001009	\end{figure*}
L001010	Next, we define the connectivity of the system as follows:
L001011	We say that two degrees of freedom $x_j$ and $x_h$ are connected if $A_{jh} \neq 0$ or $A_{hj} \neq 0$, i.~e.~if $x_j$ and $x_h$ are not connected then $A_{jh} = A_{hj} = 0$.
L001012	We choose a set $a^* \subset \lbrace 1,\ldots,D \rbrace$ of degrees of freedom to which we apply the perturbation and define the set of neighbors $N(a^*)$ as all degrees of freedom that are connected to any degree of freedom in $a^*$ but not themselves contained in $a^*$, i.~e.
L001013	\begin{align}
L001014	N(a^*) = \lbrace j \vert h \in a^* \ \text{and} \ x_j \ \text{connected to} \ x_h \rbrace/a^* .
L001015	\end{align}
L001016	We now take $a = a^* \cup N(a^*)$, that is the perturbed degrees of freedom and their neighbors, as the \enquote{active} degrees of freedom.
L001017	In addition, we assume that the diffusion matrix $B_a$ is block-diagonal in $a^*$ and $N(a^*)$,
L001018	\begin{align}
L001019	\bm{B}_a = \begin{pmatrix} \bm{B}_{a^*} & \bm{0} \\ \bm{0} & \bm{B}_{N(a^*)} \end{pmatrix} ,
L001020	\end{align}
L001021	see Fig.~\ref{fig-partition} for an illustration.
L001022	Compared to the above, the difference is that we only apply the perturbation to a subset of degrees of freedom in $a$.
L001023	Since, by definition, $a$ includes all degrees of freedom connected to any degree of freedom in $a^*$, $\bm{A}_{a^*p} = \bm{A}_{p a^*} = 0$, allowing us to partition the coupling matrix as illustrated in Fig.~\ref{fig-partition}.
L001024	Since the perturbation is only acting on $a^*$, that is, only the rows of $\bmc{Y}$ corresponding to $\bm{a}^*$ are non-zero, which we indicate by writing $\bmc{Y}_{a^*}$, we find by combining \eqref{response-equality-4} and \eqref{woodbury},
L001025	\begin{align}
L001026	\bmc{R}_a(\omega)^\text{H} &\bmc{S}_{aa}(\omega)^{-1} \bmc{R}_a(\omega) = \frac{1}{2} \bmc{Y}_{a^*}^\text{T} \bigg( \Big( \bm{B}_a + \bm{A}_{ap} \big(\bm{A}_{pp} - i \omega \bm{I} \big)^{-1} \bm{B}_p \big(\bm{A}_{pp}^\text{T} + i \omega \bm{I} \big)^{-1} \bm{A}_{ap}^\text{T} \Big)^{-1} \bigg)_{a^* a^*} \bmc{Y}_{a^*} \\
L001027	&= \frac{1}{2} \bmc{Y}_{a^*}^\text{T} \Big( \bm{B}_{a^*}^{-1} - \bm{B}_{a^*}^{-1} \bm{A}_{a^*p} \Big( \bm{A}_{ap}^\text{T} \bm{B}_a^{-1} \bm{A}_{ap} + \big(\bm{A}_{pp}^\text{T} + i \omega \bm{I} \big) \bm{B}_p^{-1} \big(\bm{A}_{pp} - i \omega \bm{I} \big) \Big)^{-1}  \bm{A}_{a^*p}^\text{T} \bm{B}_{a^*}^{-1} \Big) \bmc{Y}_{a^*}  \nn
L001028	&= \frac{1}{2} \bmc{Y}_{a^*}^\text{T} \bm{B}_{a^*}^{-1} \bmc{Y}_{a^*} = \bmc{A} \n .
L001029	\end{align}
L001030	The above result implies that, under the assumption of a block-diagonal diffusion matrix (in particular for a diagonal diffusion matrix), it is sufficient to measure the perturbed degrees of freedom and their neighbors, i.~e.~degrees of freedom that directly interact with the perturbed ones, to realize equality in the finite-frequency FRI \eqref{app-fffri}.
L001031	This result can potentially be used to localize perturbations in linear networks:
L001032	If a measured set of degrees of freedom yields equality in \eqref{app-fffri}, this implies that the perturbation is localized in the interior of the set.
L001033	By dropping degrees of freedom from the measurement one by one and checking whether the equality is still satisfied, the degrees of freedom directly affected by the perturbation can be identified.
L001034	
L001035	The above argument can also be applied to the underdamped case, since, by assumption, the matrices $\bm{m}$, $\bm{\gamma}$ and $\bm{T}$ are diagonal.
L001036	Thus, the only off-diagonal contributions stem from the coupling matrix $\bm{K}$, which has the same structure as the matrix $\bm{A}$ above.
L001037	When computing the block-inverse to obtain the response function of the phase-space observables as in \eqref{response-block-inverse}, the only non-trivial contribution arises from the these non-diagonal parts of the coupling matrix.
L001038	
L001039	\section{Response and fluctuations from Langevin simulations}
L001040	In the main text, we consider the diffusion of an underdamped particle in a tilted periodic potential, \eqref{langevin-perpot}.
L001041	We simulate this Langevin equation using the stochastic integrator developed in Ref.~\cite{Bussi2007}.
L001042	The velocity power-spectral density is calculated by computing the Fourier transform of the obtained time-discrete trajectories,
L001043	\begin{align}
L001044	\hat{v}_j = \Delta t \sum_{k = 1}^{N} e^{i \omega_j k \Delta t} v_k \quad \text{with} \quad \omega_j = \frac{2 \pi j}{\Delta t},
L001045	\end{align}
L001046	where $\Delta t$ is the time-step size and $v_k$, $k = 1,\ldots,N$, are the velocity values.
L001047	An estimate of the power-spectral density at $\omega_j$ is obtained as
L001048	\begin{align}
L001049	S_v(\omega_j) = \frac{1}{N \Delta t} \Av{\Vert \hat{v}_j \Vert^2},
L001050	\end{align}
L001051	where the average is taken over sample trajectories.
L001052	In order to account for aliasing due to the finite time-step \cite{Smith1999}, the power-spectral density shown in Fig.~\ref{fig-perpot} of the main text is the corrected spectral density,
L001053	\begin{align}
L001054	\bar{S}_v(\omega_j) = S_v(\omega_j) \frac{\sin\big(\frac{1}{2} \omega_j \Delta t\big)^2}{\big(\frac{1}{2} \omega_j \Delta t\big)^2 },
L001055	\end{align}
L001056	which corresponds to applying a lowpass filter to the signal.
L001057	In order to measure the frequency response, we apply a perturbation of the form $\epsilon g_0 \sin(\omega t)$ to the system.
L001058	We then fit the resulting average velocity with the function
L001059	\begin{align}
L001060	v_0 + \delta v \sin(\omega t + \phi) ,
L001061	\end{align}
L001062	where $v_0$, $\delta v$ and $\phi$ are fit parameters.
L001063	Since the real and imaginary parts of the response function correspond to the in-phase and out-of-phase response, respectively, they are related to the fit parameters as
L001064	\begin{align}
L001065	\Av{v}_\text{st} = v_0, \qquad \vert \bmc{R}_v(\omega) \vert = \frac{\delta v}{\epsilon}, \qquad \frac{\bmc{R}_v''(\omega)}{\bmc{R}_v'(\omega)} = \tan(\phi) ,
L001066	\end{align}
L001067	which, in particular, allows us to obtain the magnitude of the response $\vert \bmc{R}_v(\omega) \vert$ from the magnitude of the time-periodic part of the response.
